READ.add('de', {
  books: [
    // ============================================================ B1: the land’s own history of the Hush (Präteritum, as chronicles are written)
    { id: 'de.glocken', band: 3, title: 'Die acht Glocken', en: 'The Eight Bells: a chronicle of the valley', by: 'Heinrich Buchholz, librarian of Alba', from: 'A chronicle of the valley',
      blurb: 'Why does every corner of the valley have a bell? Herr Buchholz spent years listening to the old people of Alba, Molinar and Remanso. This is what they remember: the first Hush, the bell founders, and the Festival of Voices.',
      cover: { bg: '#5a3a2e', ink: '#f2d98a', icon: 'bell' },
      gloss: { 'Chronik': 'chronicle', 'Einzelheiten': 'details', 'klapperten': 'clattered (klappern)', 'Händler': 'traders, sellers', 'nachsangen': 'sang back, copied (nachsingen)', 'eines Herbstes': 'one autumn',
        'ins Leere': 'into nothing, into space', 'Schmiedin': 'blacksmith (a woman)', 'Amboss': 'anvil', 'erträgt': 'can stand, puts up with (ertragen)', 'beschloss': 'decided (beschließen)', 'Gegend': 'area, region',
        'Grube': 'pit', 'Form': 'mold', 'Lehm': 'clay, loam', 'schmilzt': 'melts (schmelzen)', 'Kupfer': 'copper', 'Zinn': 'tin', 'flüssig': 'liquid', 'flüssige': 'liquid', 'fließt': 'flows (fließen)', 'abkühlen': 'to cool down',
        'tagelang': 'for days', 'behalten': 'kept (behalten)', 'Spruch': 'a saying, a motto', 'Sprüche': 'sayings, mottos', 'Gong': 'gong (the mine’s bell)', 'Sonnenaufgang': 'sunrise', 'zugleich': 'at the same time',
        'Schüchternen': 'the shy ones', 'vergingen': 'went by (vergehen)', 'staubig': 'dusty', 'Zeug': 'stuff', 'sei': 'was, is (reported speech: «sein»)', 'seien': 'are (reported speech: «sein»)', 'hinaufzusteigen': 'to climb up (hinaufsteigen)',
        'Glöckner': 'bell ringer', 'Seil': 'rope', 'Traurigkeit': 'sadness', 'verbinden': 'connect, bring together', 'Bibliothekar': 'librarian', 'Grete': 'Grete (a name)', 'kennt': 'knows (kennen)', 'kommt': 'comes (kommen)',
        'Heinrich': 'Heinrich (a name)', 'Buchholz': 'Buchholz: Herr Buchholz, Alba’s librarian' },
      pages: [
        [['Eine Chronik ist ein Buch, in dem man aufschreibt, was passiert ist, damit es niemand vergisst.', 'A chronicle is a book in which you write down what happened, so that nobody forgets it.'],
          ['An dieser Chronik habe ich viele Jahre geschrieben.', 'I worked on this chronicle for many years.'],
          ['Ich habe mit den alten Leuten in Alba, Molinar und Remanso gesprochen, und ich habe alte Briefe und Kalender gelesen.', 'I talked with the old people of Alba, Molinar and Remanso, and I read old letters and calendars.'],
          ['Manche erinnerten sich an viele Einzelheiten, andere nur an ein Lied oder an einen Namen.', 'Some remembered lots of details; others only a song or a name.'],
          ['Vielleicht ist nicht alles hier wahr. Aber alles ist wichtig.', 'Maybe not everything here is true. But all of it matters.']],
        [['Früher war unser Tal das lauteste Tal im ganzen Land.', 'Long ago our valley was the loudest valley in the whole land.'],
          ['In Molinar klapperten die Mühlen von morgens bis abends.', 'In Molinar the mills clattered from morning till night.'],
          ['Auf den Märkten riefen die Händler ihre Preise, und auf den Festen sang und tanzte man bis spät in die Nacht.', 'In the markets the sellers called out their prices, and at festivals people sang and danced late into the night.'],
          ['Die Fischer von Remanso sangen beim Rudern, und aus der Mine hörte man den Gruß der Bergleute: „Glück auf!“', 'The fishermen of Remanso sang as they rowed, and from the mine you could hear the miners’ greeting: “Glück auf!”'],
          ['Man erzählt sogar, dass die Vögel die Lieder der Menschen nachsangen.', 'People even say the birds sang the people’s songs back to them.']],
        [['Doch eines Herbstes kam aus dem Norden ein grauer Nebel.', 'But one autumn a gray fog came down from the north.'],
          ['Zuerst dachte niemand an etwas Schlimmes: Es war eben Herbst, und im Herbst gibt es Nebel.', 'At first nobody thought anything bad: it was autumn, after all, and in autumn there’s fog.'],
          ['Aber dann hörten die Vögel auf zu singen, und die Menschen sprachen jeden Tag weniger.', 'But then the birds stopped singing, and people spoke less every day.'],
          ['Zuerst vergaßen sie die schweren Wörter, dann die leichten.', 'First they forgot the hard words, then the easy ones.'],
          ['Am Ende standen viele nur noch still und grau auf der Straße und schauten ins Leere.', 'In the end many of them just stood in the street, still and gray, staring into nothing.'],
          ['So begann das, was die Großeltern „die erste Stille“ nennen.', 'That’s how what the grandparents call “the first Hush” began.']],
        [['Niemand wusste, was man tun sollte, bis eine junge Schmiedin in Molinar etwas entdeckte.', 'Nobody knew what to do, until a young blacksmith in Molinar discovered something.'],
          ['Sie hieß Grete. Mitten im Nebel schlug sie mit ihrem Hammer auf den Amboss, so fest sie konnte.', 'Her name was Grete. In the middle of the fog she struck her anvil with her hammer, as hard as she could.'],
          ['Der Ton war so laut, dass er durch die ganze Stadt klang.', 'The sound was so loud that it rang through the whole town.'],
          ['Die Leute in der Nähe hoben die Köpfe, als ob sie aus einem Traum aufwachten.', 'The people nearby lifted their heads, as if they were waking from a dream.'],
          ['Da verstand man: Die Stille erträgt keine lauten Töne und keine Stimmen, die zusammen klingen.', 'Then people understood: the Hush can’t stand loud sounds, or voices that ring out together.'],
          ['Deshalb beschloss das Tal, acht Glocken zu gießen, eine für jede Gegend.', 'So the valley decided to cast eight bells, one for each region.']],
        [['Eine Glocke zu gießen ist schwer, und es dauert lange.', 'Casting a bell is hard, and it takes a long time.'],
          ['Zuerst baut man in einer tiefen Grube eine Form aus Lehm.', 'First you build a mold out of clay in a deep pit.'],
          ['Dann schmilzt man Kupfer und Zinn in einem sehr heißen Ofen, bis das Metall flüssig ist und leuchtet wie die Sonne.', 'Then you melt copper and tin in a very hot furnace, until the metal is liquid and glows like the sun.'],
          ['Das flüssige Metall fließt in die Form, und dann muss es tagelang abkühlen.', 'The liquid metal flows into the mold, and then it has to cool for days.'],
          ['Grete und die Leute aus Molinar sangen die ganze Zeit neben der Grube, Tag und Nacht.', 'Grete and the people of Molinar sang beside the pit the whole time, day and night.'],
          ['So, sagt man, hat jede Glocke ein bisschen von der Stimme ihrer Stadt behalten. Darum klingen keine zwei Glocken gleich.', 'That way, they say, each bell kept a little of its town’s voice. That’s why no two bells sound the same.']],
        [['Jede Glocke bekam einen Namen und einen Spruch. Das ist bei uns eine alte Tradition.', 'Each bell got a name and a motto. That’s an old tradition here.'],
          ['Auf der Glocke von Molinar steht: „Ich wecke, wer schläft.“', 'On the bell of Molinar it says: “I wake whoever sleeps.”'],
          ['Auf der Glocke vom Spiegelsee steht: „Ich singe mit dem Wasser.“', 'On the bell of the Mirror Lake it says: “I sing with the water.”'],
          ['Und auf dem Gong in der Mine steht: „Glück auf, auch im Dunkeln.“', 'And on the gong in the mine it says: “Glück auf, even in the dark.”'],
          ['Die Sprüche der anderen Glocken kenne ich nicht. Vielleicht findest du sie eines Tages.', 'I don’t know the mottos of the other bells. Maybe you’ll find them one day.']],
        [['Jeden Frühling feierte das Tal das Fest der Stimmen.', 'Every spring the valley celebrated the Festival of Voices.'],
          ['Bei Sonnenaufgang läuteten alle Glocken zugleich.', 'At sunrise all the bells rang at once.'],
          ['Danach sagte jeder Mensch seinen Namen laut, vor der ganzen Stadt.', 'Then every person said their name out loud, in front of the whole town.'],
          ['Die Kinder schrien ihn, die Alten sangen ihn, und die Schüchternen … die sagten ihn eben, so gut sie konnten.', 'The children shouted it, the old folks sang it, and the shy ones… well, they said it as best they could.'],
          ['Niemand lachte über jemanden, denn die wichtigste Regel des Festes war: „Jede Stimme zählt.“', 'Nobody laughed at anybody, because the festival’s most important rule was: “Every voice counts.”']],
        [['Die Jahre vergingen, und die Stille kam nicht zurück.', 'The years went by, and the Hush didn’t come back.'],
          ['Langsam vergaßen die Leute das Fest.', 'Slowly people forgot the festival.'],
          ['Die Glocken wurden staubig, und niemand läutete sie mehr.', 'The bells grew dusty, and nobody rang them anymore.'],
          ['Die Jungen sagten, das sei „altes Zeug“, und die Alten hatten keine Kraft mehr, auf die Türme hinaufzusteigen.', 'The young said it was “old stuff”, and the old no longer had the strength to climb up the towers.'],
          ['Heute wissen viele nicht einmal mehr, dass es diese Glocken gibt.', 'Today many people don’t even know these bells exist.']],
        [['Mein Großvater war der letzte Glöckner von Alba. Als ich sieben war, nahm er mich mit auf den Glockenturm.', 'My grandfather was Alba’s last bell ringer. When I was seven, he took me up the bell tower with him.'],
          ['Das Seil war dicker als mein Arm, und ich hatte Angst vor der Höhe.', 'The rope was thicker than my arm, and I was afraid of the height.'],
          ['„Eine Glocke läutet man nicht mit den Armen“, sagte er, „sondern mit dem ganzen Herzen.“', '“You don’t ring a bell with your arms,” he said, “but with your whole heart.”'],
          ['Dann zogen wir zusammen am Seil, und die Glocke sang über das ganze Tal.', 'Then we pulled the rope together, and the bell sang out over the whole valley.'],
          ['Diesen Ton habe ich nie vergessen.', 'I’ve never forgotten that sound.']],
        [['Jetzt ist die Stille zurück, und wieder kam sie aus dem Norden.', 'Now the Hush is back, and once again it came from the north.'],
          ['Woher kommt sie? Das weiß niemand genau.', 'Where does it come from? Nobody knows for sure.'],
          ['Manche sagen, sie ist ein kalter Wind aus den Bergen.', 'Some say it’s a cold wind from the mountains.'],
          ['Andere glauben, sie ist eine Traurigkeit, die so groß geworden ist, dass sie zu Nebel wurde.', 'Others believe it’s a sadness that grew so big it turned into fog.'],
          ['Ich weiß nicht, wer recht hat. Aber eines weiß ich: Die Stille hat Angst vor Wörtern, weil Wörter uns verbinden.', 'I don’t know who’s right. But I do know one thing: the Hush is afraid of words, because words bring us together.']],
        [['Deshalb lesen wir in dieser Bibliothek laut.', 'That’s why we read out loud in this library.'],
          ['Wenn du ein Wort nicht kennst, frag. Wenn du einen Fehler machst, ist das egal: Sprich weiter.', 'If you don’t know a word, ask. If you make a mistake, it doesn’t matter: keep talking.'],
          ['Ein Wort mit Fehlern ist besser als tausend Wörter, die niemand sagt.', 'One word with mistakes is better than a thousand words nobody says.'],
          ['Und wenn dir jemand erzählt, Glocken seien „altes Zeug“, dann erzähl ihm diese Geschichte.', 'And if anyone ever tells you bells are “old stuff”, tell them this story.'],
          ['Heinrich Buchholz, Bibliothekar von Alba', 'Heinrich Buchholz, librarian of Alba']],
      ],
      retell: { ask: 'Erzähl die Geschichte der Glocken mit deinen Worten: Was ist zuerst passiert, und was danach?', en: 'Tell the story of the bells in your own words: what happened first, and what happened after?',
        want: { points: [['Nebel', 'grau', 'Stille', 'Norden'], ['Glocke', 'Glocken', 'gießen', 'gegossen'], ['Fest', 'Stimme', 'Stimmen', 'Name', 'Namen'], ['vergessen', 'vergaßen', 'staubig', 'Staub', 'Zeug'], ['Amboss', 'Hammer', 'Schmiedin', 'laut', 'Ton']], enough: 3, min: 12, time: 'past' },
        starter: 'Vor langer Zeit kam ___. Deshalb ___.', hint: 'The fog from the north → Grete’s hammer → the eight bells → the festival → forgetting → now.',
        model: 'Vor langer Zeit kam ein grauer Nebel aus dem Norden, und die Leute haben aufgehört zu sprechen. Eine junge Schmiedin hat entdeckt, dass laute Töne helfen. Deshalb hat das Tal acht Glocken gegossen. Später haben die Leute das Fest vergessen, und jetzt ist die Stille zurück.' },
      q: [
        { ask: 'Was hat die junge Schmiedin entdeckt?', en: 'What did the young blacksmith discover?', want: { lemmas: ['laut', 'Ton', 'Töne', 'Lärm', 'Krach', 'Hammer', 'Amboss', 'aufwachen', 'wach', 'Klang', 'klingen'] },
          starter: 'Sie hat entdeckt, dass ___.', hint: 'Page 4: her hammer, the anvil…', model: 'Sie hat entdeckt, dass laute Töne die Leute aus der Stille holen.', simple: 'Was ist passiert, als sie auf den Amboss geschlagen hat?' },
        { ask: 'Warum haben die Leute aufgehört, die Glocken zu läuten?', en: 'Why did people stop ringing the bells?', want: { lemmas: ['vergessen', 'vergaßen', 'Staub', 'staubig', 'Zeug', 'Kraft', 'Jahre', 'Fest'] },
          starter: 'Weil ___.', hint: 'Page 8: the years went by…', model: 'Weil die Stille viele Jahre nicht zurückgekommen ist und die Leute das Fest vergessen haben.', simple: 'Haben die Leute das Fest vergessen?' },
        { ask: 'Und du? Woher kommt die Stille, glaubst du? Warum?', en: 'And you? Where do you think the Hush comes from? Why?', want: { any: true, min: 4 },
          starter: 'Ich glaube, dass ___, weil ___.', hint: 'There’s no wrong answer: give your opinion and a reason («weil …»).', model: 'Ich glaube, dass die Stille eine große Traurigkeit ist, weil traurige Menschen weniger reden.' },
      ],
      after: 'Someone has drawn a tiny bell in the margin of the last page, and written «N.» beside it…' },
  ],
});

